#!/usr/bin/env bash
# shellcheck disable=SC2034,SC2088  # I18N_EN lib/i18n.sh içinde kullanılır; ~ metindir, yol değil
# ============================================================================
# Terminal Setup - English catalog: kurulumun ürettiği dosyalar
